import primitive_api as p
import json

def compact_world():
    obs = p.observe_world()
    show("state", {k: obs.get(k) for k in ("world_steps", "agentLocation", "lastActionMessage", "extended_action_message") if k in obs})
    return obs

compact_world()

def act(name, **kwargs):
    validation = p.validate_action_call(name, kwargs)
    if not validation.get("ok", False):
        show("invalid_action", validation)
        return None
    result = getattr(p, name)(**kwargs)
    if isinstance(result, dict):
        show(name, {k: v for k, v in result.items() if k not in ("observation", "current_observation", "nearby_objects", "inventory", "accessible_objects")})
    else:
        print(name, str(result)[:1600])
    return result

def approach(uuid, limit=8):
    for _ in range(limit):
        accessible = p.list_accessible_objects()
        if any(o["uuid"] == uuid for o in accessible):
            return True
        matches = [o for o in p.list_nearby_objects(query=str(uuid)) if o["uuid"] == uuid]
        if not matches:
            print("Target no longer nearby", uuid)
            return False
        target = matches[0]
        directions = target["direction"].split("-")
        if target["distance"] == 1 and len(directions) == 1:
            act("rotate_direction", direction=directions[0])
        elif directions[0] in ("north", "east", "south", "west"):
            act("move_direction", direction=directions[0])
        else:
            print("Cannot resolve approach", target)
            return False
    return False

for tool_id in (4766, 60834, 53954):
    if approach(tool_id):
        act("pickup_object", obj=tool_id)
    else:
        print("Could not reach tool", tool_id)
        break

show("inventory", p.list_inventory())
if all(any(o["uuid"] == uid for o in p.list_inventory()) for uid in (4766, 60834, 53954)):
    p.write_evidence("navigation", {"method": "official named teleport", "destination": "dig site 1"})
    act("teleport_to_location", location_name="dig site 1")
    compact_world()
    show("site_accessible", p.list_accessible_objects())
    show("site_nearby", [o for o in p.list_nearby_objects() if o["name"] not in ("grass", "plant", "agent")])
show("verification", p.check_success())

import primitive_api as p
import json

def brief(value):
    if isinstance(value, dict):
        out = {}
        for k, v in value.items():
            if k in ("agentLocation", "world_steps", "lastActionMessage", "extended_action_message",
                     "success", "valid_action", "error", "errors", "message", "completed",
                     "completedSuccessfully", "score", "verification"):
                out[k] = v
            elif isinstance(v, dict):
                child = brief(v)
                if child:
                    out[k] = child
        return out
    return {}

