def approach(uuid, limit=12):
    visits = {}
    offsets = {"north": (0, -1), "east": (1, 0),
               "south": (0, 1), "west": (-1, 0)}
    for _ in range(limit):
        obs = p.observe_world()
        if any(o["uuid"] == uuid for o in obs.get("accessibleEnvironmentObjects", [])):
            return True
        matches = [o for o in p.list_nearby_objects(query=str(uuid))
                   if o["uuid"] == uuid]
        if not matches:
            print("Target outside nearby view", uuid)
            return False
        target = matches[0]
        loc = obs["agentLocation"]
        position = (loc["x"], loc["y"])
        visits[position] = visits.get(position, 0) + 1
        desired = target["direction"].split("-")
        if target["distance"] == 1 and len(desired) == 1:
            result = act("rotate_direction", direction=desired[0])
        else:
            allowed = loc.get("directions_you_can_move", [])
            if not allowed:
                return False
            def cost(direction):
                dx, dy = offsets[direction]
                destination = (position[0] + dx, position[1] + dy)
                return 4 * visits.get(destination, 0) + (0 if direction in desired else 2)
            direction = min(allowed, key=cost)
            result = act("move_direction", direction=direction)
        if result is None:
            return False
    return any(o["uuid"] == uuid for o in p.list_accessible_objects())

