show("current", brief(p.observe_world()))
cell_actions = 0
verification = p.check_success()
show("verification_before", verification)

if not verification.get("completed", False):
    ages = {
        site: max(m["age_years"] for m in record["measurements"]
                  if isinstance(m.get("age_years"), (int, float)))
        for site, record in summary.items()
        if any(isinstance(m.get("age_years"), (int, float))
               for m in record["measurements"])
    }
    show("measured_ages", ages)
    if len(ages) == 3:
        oldest_site = max(ages, key=ages.get)
        sign_id = summary[oldest_site]["sign"]
        p.write_evidence("selection", {
            "site": oldest_site,
            "age_years": ages[oldest_site],
            "reason": "Largest measured artifact age across all three excavated sites."
        })
        p.write_evidence("navigation", {
            "method": "official named teleport",
            "destination": oldest_site
        })
        act("teleport_to_location", location_name=oldest_site)
        if approach(sign_id, limit=8):
            act("read_object", obj=sign_id)
            nearby_signs = p.list_nearby_objects(query=str(sign_id))
            adjacent = any(o["uuid"] == sign_id and o["distance"] == 1
                           for o in nearby_signs)
            has_flag = any(o["uuid"] == 53954 for o in p.list_inventory())
            if adjacent and has_flag:
                placement = p.observe_world()["agentLocation"]
                act("drop_object", obj=53954)
                p.write_evidence("flag_placement", {
                    "site": oldest_site,
                    "sign": sign_id,
                    "x": placement["x"],
                    "y": placement["y"],
                    "sign_distance": 1
                })
            else:
                show("placement_not_ready", {
                    "adjacent": adjacent, "has_flag": has_flag,
                    "sign": nearby_signs
                })
    else:
        print("Missing measured age for a site; flag placement deferred.")

show("verification_after", p.check_success())
